import _codecs
class Map:
    def __getitem__(self, key):
        print(input(), key)
        return ''
print(repr(_codecs.charmap_decode(b'AB', 'strict', Map())))

import _codecs
class Map:
    def __getitem__(self, key):
        print(input(), key)
        return 'A🐍'
print(repr(_codecs.charmap_decode(b'AB', 'strict', Map())))

import _codecs
def recover(error):
    print(input(), type(error).__name__, error.start, error.end, repr(error.object))
    return ('🐍', -1)
_codecs.register_error('recovery', recover)
print(repr(_codecs.charmap_decode(b'AB', 'recovery', {66: 67})))

import _codecs
class Map:
    def __getitem__(self, key):
        print(input(), key)
        raise ValueError('mapping failed')
try:
    _codecs.charmap_decode(b'A', 'strict', Map())
except ValueError as error:
    print(type(error).__name__, repr(error.args))
